-- 1. Tribunal Constitucional (fonction 253 - PT-c) INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Portugal – Tribunal Constitucional', 'Juges conseillers du Tribunal constitutionnel du Portugal (catégorie PT-c)', 'pt_pep_constitutional_court', 'PEP', 'https://www.tribunalconstitucional.pt/', 'pt-pep-constitutional-court', 'D:/test parser 2/plugins/swiftcheck-aml-pt-pep-constitutional-court-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'API', NULL, '{"url": "https://www.tribunalconstitucional.pt/tc/juizes.html"}', 168, 12, 'Données publiques ouvertes : citer la source', 'Tribunal Constitucional de Portugal', 'Président, Vice-Président et juges conseillers du Tribunal constitutionnel (Palácio Ratton).', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Président, Vice-Président et ensemble des juges conseillers du Tribunal constitutionnel', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.country_iso = 'PT' AND f.id = 253 AND p.dataset_name = 'pt_pep_constitutional_court';
-- 2. Supremo Tribunal de Justiça et STA (fonction 254 - PT-c) INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Portugal – Hautes Cours Suprêmes STJ et STA', 'Juges conseillers de la Cour suprême de justice et de la Cour suprême administrative (catégorie PT-c)', 'pt_pep_supreme_courts', 'PEP', 'https://www.stj.pt/', 'pt-pep-supreme-courts', 'D:/test parser 2/plugins/swiftcheck-aml-pt-pep-supreme-courts-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'API', NULL, '{"url": "https://www.stj.pt/"}', 168, 12, 'Données publiques ouvertes : citer la source', 'Supremo Tribunal de Justiça e Supremo Tribunal Administrativo', 'Présidents, Vice-Présidents et présidents de section du STJ et du STA.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Présidents, Vice-Présidents et magistrats de haut rang du STJ et du STA', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.country_iso = 'PT' AND f.id = 254 AND p.dataset_name = 'pt_pep_supreme_courts';
