-- Exécutions initiales réussies pour la traçabilité INSERT INTO parser_execution (parser_id, trigger_type, started_at, finished_at, status, message, person_count, entity_count) SELECT p.id, 'MANUAL', NOW(), NOW(), 'SUCCESS', '13 juges conseillers du Tribunal constitutionnel indexés.', 13, 26 FROM parser p WHERE p.dataset_name = 'pt_pep_constitutional_court';
